    ('art_sock', 'Носок с дыркой', 'common', 3000, 'artifact', 'Дырявый, но рыбу почему-то притягивает. Чем больше дырка, тем больше рыбы. И мусора.', 1, null, '{}'::jsonb, '{}'::jsonb),
    ('art_compass', 'Компас утопленника', 'common', 3000, 'artifact', 'Стрелка всегда показывает вниз, к сокровищам. Но идти за ней приходится медленно.', 1, null, '{}'::jsonb, '{}'::jsonb),
    ('art_copper_coin', 'Медяк на счастье', 'common', 3000, 'artifact', 'Одна монета, протёртая до блеска. Платит понемногу за каждый заброс удочки, но пустых становится чуть больше.', 1, null, '{}'::jsonb, '{}'::jsonb),
    ('art_dry_rag', 'Сухая тряпка', 'common', 3000, 'artifact', 'Вытирать руки — тоже навык. Забросы удочки выходят быстрее, а мусора на крючке чуть меньше.', 1, null, '{}'::jsonb, '{}'::jsonb),
    ('art_spoon', 'Позолоченная ложка деда', 'uncommon', 12000, 'artifact', 'Дед говорил, что ложка приносит деньги. Дед врал, но монеты всё же появляются — правда, рыбы меньше.', 8, null, '{}'::jsonb, '{}'::jsonb),
    ('art_lucky_scale', 'Счастливая чешуйка', 'uncommon', 12000, 'artifact', 'Владелец был очень удачлив — и очень мёртв. Редкой добычи больше, но пустых забросов удочки тоже.', 8, null, '{}'::jsonb, '{}'::jsonb),
    ('art_bent_nail', 'Гнутый гвоздь', 'uncommon', 12000, 'artifact', 'Согнут под правильным углом. Рыба иногда клюёт дважды, чтобы проверить, что это не гвоздь.', 8, null, '{}'::jsonb, '{}'::jsonb),
    ('art_whisper_shell', 'Шепчущая ракушка', 'uncommon', 12000, 'artifact', 'Если приложить к уху, слышно чужие уловы. Иногда они становятся вашими — вместе с их ошибками.', 8, null, '{}'::jsonb, '{}'::jsonb),
    ('art_glass_float', 'Стеклянный поплавок', 'rare', 35000, 'artifact', 'Не тонет. Совсем. Наживку бережёт лучше всего в мире — но забросы удочки выходят медленнее.', 20, null, '{}'::jsonb, '{}'::jsonb),
    ('art_cat_bell', 'Колокольчик кота-алкаша', 'rare', 35000, 'artifact', 'Звенит не переставая. Рыба клюёт дважды, мусор — трижды.', 20, null, '{}'::jsonb, '{}'::jsonb),
    ('art_sunken_key', 'Ключ от затонувшего сундука', 'rare', 35000, 'artifact', 'Сундук давно уплыл, но замки почему-то всё ещё его узнают. Сокровищ много, рыбы — меньше.', 20, null, '{}'::jsonb, '{}'::jsonb),
    ('art_moon_pearl', 'Лунный жемчуг', 'rare', 35000, 'artifact', 'Светится в темноте и притягивает эпическую добычу. Но пока светит — заброс удочки занимает дольше.', 20, null, '{}'::jsonb, '{}'::jsonb),
    ('art_abyss_eye', 'Глаз Бездны', 'epic', 80000, 'artifact', 'Смотрит в ответ. В удачный день подкидывает эпическую добычу, но обычно отпугивает рыбу и зовёт пустоту.', 30, null, '{}'::jsonb, '{}'::jsonb),
    ('art_horseshoe', 'Ржавая подкова на удачу', 'epic', 80000, 'artifact', 'Тяжёлая, ржавая и невероятно удачливая. Ускоряет забросы и платит золотом — за счёт сокровищ.', 30, null, '{}'::jsonb, '{}'::jsonb),
    ('art_tide_clock', 'Приливные часы', 'epic', 80000, 'artifact', 'Идут строго по приливу: самый быстрый заброс в игре. Но прилив уносит наживку и оставляет пустоту.', 30, null, '{}'::jsonb, '{}'::jsonb),
    ('art_drowned_map', 'Карта утопленника', 'epic', 80000, 'artifact', 'Нарисована на чьей-то рубашке. Сокровища и редкая добыча идут вместе — но золота на карте нет.', 30, null, '{}'::jsonb, '{}'::jsonb),
    ('art_tide_crown', 'Корона Прилива', 'legendary', 180000, 'artifact', 'Прилив её слушается через раз. Сокровищ становится заметно больше, пустых забросов — тоже.', 40, null, '{}'::jsonb, '{}'::jsonb),
    ('art_invisible_rod', 'Удочка, которой не было', 'legendary', 180000, 'artifact', 'Её нет, но она ловит. Иногда дважды. Иногда мифическую рыбу. Иногда — только мусор.', 40, null, '{}'::jsonb, '{}'::jsonb),
    ('art_siren_harp', 'Арфа сирены', 'legendary', 180000, 'artifact', 'Играет одну ноту — ту самую, после которой рыба становится легендарной. И уплывает.', 40, null, '{}'::jsonb, '{}'::jsonb),
    ('art_midas_hook', 'Крючок Мидаса', 'legendary', 180000, 'artifact', 'Всё, что касается крючка, становится золотым. Сокровища тоже, но с рыбой крючок не дружит.', 40, null, '{}'::jsonb, '{}'::jsonb),
    ('art_poseidon_seal', 'Печать Посейдона', 'mythic', 400000, 'artifact', 'Подпись бога на дне морском. Уважают её почти все, но пока печать действует, забросы медленнее.', 50, null, '{}'::jsonb, '{}'::jsonb),
    ('art_fate_sock', 'Носок Судьбы', 'mythic', 400000, 'artifact', 'Второй носок из пары. Второй карман в инвентаре и золото — но удача всё ещё пропала, и забросы медленнее.', 50, null, '{}'::jsonb, '{}'::jsonb),
    ('art_world_anchor', 'Якорь мира', 'mythic', 400000, 'artifact', 'Держит на месте целый залив. Сокровища собираются сами, но вместе с ними — пустота и расходы.', 50, null, '{}'::jsonb, '{}'::jsonb),
    ('art_star_scale', 'Звёздная чешуя', 'mythic', 400000, 'artifact', 'Упала с неба в воду. Обычно только мешает ловить, но в редкий момент притягивает мифическую рыбу.', 50, null, '{}'::jsonb, '{}'::jsonb),
    ('scroll_of_cleansing', 'Свиток очищения', 'rare', 0, 'consumable', 'Сжигает проклятие артефакта и заново роллит его обычные эффекты. Очень редкая находка.', 1, null, '{}'::jsonb, '{}'::jsonb)
